const STATIONS=[20,25,30,35,40,45,50,55,60,65,70];
const CLASS_INDEX={low_class:0,working_class:1,middle_class:2,bureaucratic_class:3,high_class:4};
// Three things, chosen once per life, weighted by the class you were born into.
export function directorSchedule(seed,cls){
 const c=CLASS_INDEX[cls]??2,out={},used=new Set();
 for(let n=0;n<3;n++){const pool=DIRECTOR_SCENES.filter(s=>!used.has(s.id)&&s.odds[c]>0),total=pool.reduce((a,s)=>a+s.odds[c],0);let at=rand(seed,n,'director')*total,pick=pool.at(-1);for(const s of pool)if((at-=s.odds[c])<0){pick=s;break;}used.add(pick.id);const fit=STATIONS.filter(a=>a>=pick.min&&a<=pick.max&&!out[a]);if(fit.length)out[fit[Math.floor(rand(seed,n,'director-age')*fit.length)]]=pick.id;}
 return out;
}
const cast=s=>directorSchedule(s.seed,s.intake?.class??s.birth?.class);
const freeFirst=l=>[...l.filter(o=>!(o.cash<0)),...l.filter(o=>o.cash<0)];
// Priority 2 with the director flag: it takes a quiet station, never a wedding or a piece of history.
export const DIRECTOR_ENCOUNTERS=DIRECTOR_SCENES.map(({odds,needs,options,...scene})=>({...scene,options:freeFirst(options),director:true,eligible:s=>!!s.intake?.class&&cast(s)[s.age]===scene.id&&(!needs||needs(s))}));

// The saddest things that really happen here, each resting on a source the note names.
// The situations are composites; the numbers are not. Rare per life, and only in their years.
const SAD_SCENES=[
 {id:"s_loan",category:"money",min:18,max:70,from:1980,to:2026,gate:null,title:"The man on the motorbike",prompt:"The rice has gone and the school wants its fee. A man on a motorbike will lend you five thousand today, no paper, twenty percent a month. He already knows where you live.",rehearse:"This is real. A 2019 University of the Thai Chamber of Commerce survey of 1,201 people found that 40.8 percent of household debt was owed to loan sharks, and police were arresting lenders who charged up to 20 percent per day. (The ASEAN Post, 2019)",options:[opt("sell","Sell the motorbike instead",{"wellbeing": -4},"You walked to work for two years. You owed nobody."),opt("borrow","Take the money",{"cash": 5000, "wellbeing": -12},"You paid him for three years and still owed him five thousand. He was always polite."),opt("family","Go to the village fund and be embarrassed",{"wellbeing": -3, "skills": {"eq": 1}},"Everyone knew by evening. The interest was one percent.")]},
 {id:"s_title",category:"family",min:25,max:70,from:1985,to:2018,gate:"country",title:"The paper in his drawer",prompt:"Your father handed the land deed to the moneylender years ago against a small loan. The moneylender’s son now says the debt has grown and the land is his. Your family has farmed it for sixty years.",rehearse:"This is real. In 2018 the government returned 1,534 deeds worth about 3 billion baht to 1,358 Northeasterners at one ceremony in Kalasin, some of whom had lost their land almost 30 years earlier. (The Nation Thailand, 2018)",options:[opt("work","Keep working it and hope nobody comes",{"wellbeing": -6},"They came in the ninth year, with a surveyor."),opt("complain","Go to the district office with everyone else",{"wellbeing": -3, "skills": {"iq": 1}},"Four years of forms. You got the deed back, and your father did not live to see it."),opt("pay","Borrow from a bank to buy it back",{"cash": -25000, "wellbeing": -5},"You own it again. Now the bank has the paper.")]},
 {id:"s_chamoy",category:"money",min:20,max:75,from:1984,to:1985,gate:null,title:"The lady who pays six percent a month",prompt:"Everyone on your street has money with the woman from the oil company, and she has paid on time for years. Your sister doubled her savings. You have your whole retirement in a tin.",rehearse:"This is real. When the scheme was shut down in 1985, 14,166 people filed police complaints over more than 4 billion baht, and most of the money had already been withdrawn before accounts were frozen. (Bangkok Post, Thailand Journey timeline, 1985)",options:[opt("no","Keep it in the tin",{"wellbeing": -2},"Your sister stopped speaking to you when it was going well, and again when it was not."),opt("some","Put in a little",{"cash": -15000, "wellbeing": -2},"The office closed on a Tuesday. There was a crowd outside by noon, and you were in it."),opt("all","Put it all in",{"cash": -90000, "wellbeing": -16},"You stood in the police line with fourteen thousand others and filled in a form.")]},
 {id:"s_forex",category:"money",min:20,max:60,from:2021,to:2022,gate:null,title:"The group chat that pays out",prompt:"A friend from work shows you the app. Twenty percent a month, the screenshots are real, and the man running it has a car in every photograph.",rehearse:"This is real. The Forex 3D scheme, which promised returns of roughly 10 to 20 percent a month, left an estimated 13,000 or more victims and several billion baht in losses. (Thai PBS World, 2022)",options:[opt("no","Close the app",{"wellbeing": -1},"You felt stupid for about a year."),opt("try","Put in one month’s pay",{"cash": -20000, "wellbeing": -4},"It paid twice. Then the group went quiet, and then it was deleted."),opt("borrow","Borrow to put in more, and bring your sister in",{"cash": -60000, "wellbeing": -16, "flag": "broughtSister"},"The money was the smaller loss. She has not said a word about it, ever.")]},
 {id:"s_1997",category:"work",min:25,max:60,from:1997,to:1999,gate:"city",title:"The office closes in July",prompt:"The baht has gone. The finance company on the twentieth floor sent everyone home on Friday. Your car, your condo and your children’s school are all priced in a life that ended this morning.",rehearse:"This is real. AP reporting on the crisis's 20th anniversary describes a laid-off tour guide whose monthly income fell from about 3,000 US dollars to as little as 200 dollars selling fish balls on the street. (Associated Press via Taipei Times, 2017)",options:[opt("street","Sell food on the pavement in your office clothes",{"wellbeing": -6, "skills": {"drive": 2}},"People you had once given orders to bought sandwiches from you and were very kind about it."),opt("home","Take the children back to the village",{"wellbeing": -7, "skills": {"eq": 2}},"Your mother said nothing about it and killed a chicken."),opt("hold","Keep the suit on and keep applying",{"cash": -30000, "wellbeing": -10},"Fourteen months. You learned which guards let you sit in the lobby.")]},
 {id:"s_bike",category:"family",min:38,max:70,from:1990,to:2026,gate:"parent",title:"He wants the motorbike",prompt:"Your son is sixteen. All his friends ride. It is six kilometres to school and there is no bus. He has promised about the helmet.",rehearse:"This is real. WHO estimates 18,218 road deaths in Thailand in 2021, a rate of 25.4 per 100,000, and motorcyclists were 83.8 percent of all road deaths. (World Health Organization Thailand, 2023)",options:[opt("no","Refuse, and drive him yourself",{"wellbeing": -3},"He hated you for two years. He is forty now and does not remember."),opt("let","Let him borrow his cousin’s",{"wellbeing": -24, "flag": "lostSon"},"It was two in the afternoon. It was not even raining. They let you wash him."),opt("helmet","Buy it, and buy the good helmet",{"cash": -25000, "wellbeing": -1},"Nine years of being awake until you heard it come in.")]},
 {id:"s_fluke",category:"health",min:40,max:75,from:1950,to:2026,gate:"isan",title:"What you ate as a child",prompt:"You grew up on raw fish with lime, like everybody. Your stomach has hurt for a month. The doctor at the provincial hospital has already asked which village you are from.",rehearse:"This is real. A 2007 PLoS Medicine review reports that liver fluke infected about 9.4 percent of Thais in 2001, with the highest rates in the north and northeast, and Khon Kaen has the world's highest recorded bile duct cancer incidence. (PLoS Medicine (Sripa et al.), 2007)",options:[opt("now","Go for the scan this week",{"health": -10, "wellbeing": -6},"They caught it in time to give you a choice. That is what early means here."),opt("wait","Wait until after the harvest",{"health": -22, "wellbeing": -8},"After the harvest there was much less to discuss."),opt("monk","Go to the temple and ask what to do",{"health": -18, "wellbeing": -2, "skills": {"eq": 1}},"The abbot sent you to the hospital and came with you.")]},
 {id:"s_hiv",category:"health",min:20,max:40,from:1988,to:1996,gate:"man",title:"The test at the army clinic",prompt:"It is the early nineties and they are testing everyone. Your friend from your year has come back with a paper he will not show you. You went to the same places together. You have a wife now.",rehearse:"This is real. A study of 4,086 young conscripts from six northern provinces found HIV incidence of 2.48 per 100 person-years in 1991-93, falling to 0.55 in 1993-95. (AIDS journal (Celentano et al.), 1998)",options:[opt("test","Get tested and tell her the result",{"wellbeing": -10, "skills": {"eq": 3}},"It was negative. You told her why you had been afraid. That took longer to get over."),opt("no","Do not get tested",{"wellbeing": -8},"You watched your own arms for years."),opt("friend","Go and sit with your friend",{"wellbeing": -6, "skills": {"eq": 2}},"Nobody would eat with him. You did. He weighed nothing by the end.")]},
 {id:"s_skip",category:"family",min:22,max:42,from:1985,to:2026,gate:"parent",title:"Leaving her with your mother",prompt:"The factory in Samut Prakan pays three times what anyone pays here, and it has no room for a baby. Your daughter is two. Your mother says go.",rehearse:"This is real. A 2012 UNICEF-backed survey found about 21 percent of Thai children, roughly three million, did not live with their parents, and close to 30 percent in the Northeast. (The Nation Thailand, 2014)",options:[opt("stay","Stay and be poor together",{"wellbeing": 2},"She got your whole face to look at. There was no money for the upper school."),opt("go","Go, and send money home",{"cash": 30000, "wellbeing": -10, "flag": "leftChild"},"She called your mother Mae. You sent money for fourteen years and she thanked you, politely."),opt("bring","Bring her and hide her in the dormitory",{"cash": -6000, "wellbeing": -6},"She learned to be quiet by three.")]},
 {id:"s_abroad",category:"work",min:18,max:35,from:2000,to:2026,gate:"woman",title:"A restaurant job in Bahrain",prompt:"A woman from the next village, nicely dressed, has a job for you: waitress, good pay, she will advance the ticket and you pay her back from wages. Your mother’s roof is coming in.",rehearse:"This is real. The Pavena Foundation recorded 127 Thai women reporting trafficking in 2017, 125 of them forced into prostitution abroad, 50 in Bahrain alone. (The Nation Thailand, 2018)",options:[opt("no","Say no",{"wellbeing": -3},"The roof came in. Her niece took the job and nobody in the village has an address."),opt("check","Ask to see the contract and call the labour office",{"wellbeing": -1, "skills": {"iq": 2}},"The company did not exist. She stopped coming to the market."),opt("go","Go",{"wellbeing": -30, "health": -14, "cash": -40000, "flag": "trafficked"},"They took your passport at the airport. There was no restaurant. A foundation got you home in the third year.")]},
 {id:"s_pills",category:"work",min:18,max:45,from:1996,to:2019,gate:null,title:"Holding a bag for a cousin",prompt:"Your cousin asks you to keep a small packet for two days. You have seen what it is. He paid for your father’s operation. The police are at the end of the soi more than they used to be.",rehearse:"This is real. A 2019 report says 82 percent of Thai women in prison in 2018 were held for drug offences, about 90 percent of those involving methamphetamine. (IDPC (republished from Thai Examiner), 2019)",options:[opt("no","Give it back",{"wellbeing": -4},"He said he understood. He did not ask you for anything again, including to the wedding."),opt("warn","Tell him you will go to the police if he asks again",{"wellbeing": -5, "skills": {"drive": 1}},"He laughed, and then he moved."),opt("keep","Keep it for him",{"wellbeing": -26, "cash": -30000, "flag": "prison"},"Eighty pills, and you were told how long that was. Your children were tall when you came out.")]},
 {id:"s_tsunami",category:"family",min:15,max:75,from:2004,to:2004,gate:null,title:"The sea went out",prompt:"It is the morning after Christmas and you are working on the coast. The water has gone a long way out and left fish on the sand. Children are running down to pick them up. An old Moken man is shouting at everyone.",rehearse:"This is real. AP reported on the 15th anniversary that official deaths in Thailand were 8,200 to 8,300, roughly a third of them missing, and Ban Nam Khem lost about half of its 5,000 residents. (Associated Press, 2019)",options:[opt("run","Run for the hill and shout at everyone",{"wellbeing": -14, "skills": {"drive": 2}},"You got up the hill with eleven people. You can name the ones who did not listen."),opt("look","Go down and look",{"wellbeing": -22, "health": -16},"You held a coconut palm. You will not say what you let go of."),opt("child","Go back for the children on the beach",{"wellbeing": -18, "health": -10, "skills": {"eq": 3}},"You got two.")]},
 {id:"s_flood",category:"family",min:20,max:75,from:2011,to:2011,gate:null,title:"The water reaches the second step",prompt:"The radio says the walls will hold. The neighbours say they will not. The house is everything you have ever paid for, and your mother cannot climb stairs.",rehearse:"This is real. A 2013 TDRI study for ERIA says the 2011 flood affected 12.8 million people, caused 728 deaths and damage and loss of 46.5 billion US dollars. (ERIA (Poapongsakorn and Meethom, TDRI), 2013)",options:[opt("stay","Stay and guard the house",{"wellbeing": -12, "health": -8},"Forty days upstairs. The motorbike was stolen by boat."),opt("carry","Carry your mother out now",{"wellbeing": -6, "cash": -8000},"Three months on a gymnasium floor. Then the smell."),opt("sandbag","Spend what you have on sandbags",{"cash": -15000, "wellbeing": -10},"It came up through the drains.")]},
 {id:"s_rice",category:"money",min:30,max:70,from:2013,to:2014,gate:"country",title:"The receipt for your rice",prompt:"You delivered your whole crop to the government scheme, and they gave you a slip of paper. It is five months later. The slip has not become money, and the man you borrowed seed money from has started visiting.",rehearse:"This is real. After the state ran short of money to pay farmers, the Mental Health Department investigated 13 farmer suicides in early 2014, and nine of the 13 had large informal debts. (The Nation Thailand, 2014)",options:[opt("wait","Wait for the government",{"wellbeing": -12},"A neighbour who waited too drank weedkiller in February. It was in the district report as a number."),opt("protest","Take the pickup to Bangkok with the others",{"wellbeing": -5, "cash": -3000, "skills": {"drive": 1}},"You slept on the road for eleven days and were on the news for a minute. The money came in pieces."),opt("borrow","Borrow more to get to the next harvest",{"cash": -20000, "wellbeing": -9},"You were paid eventually. The interest was not refunded.")]},
 {id:"s_scam",category:"money",min:58,max:80,from:2018,to:2026,gate:null,title:"A call from the police",prompt:"A courteous officer in uniform is on video. Your bank account has been linked to a drug case, and to clear your name you must move the money to a safe account, today, and tell nobody, because the leak could be your own children.",rehearse:"This is real. The Thaiger reported in June 2024 that an 81-year-old man lost about 22 million baht, his life savings, to a caller posing as a provincial police officer. (The Thaiger, 2024)",options:[opt("hang","Hang up and ring your daughter",{"wellbeing": -1},"She shouted at you for an hour, mostly from fright."),opt("branch","Go to the bank and ask them",{"wellbeing": -2, "skills": {"iq": 1}},"The teller had seen four that month."),opt("move","Move the money",{"cash": -200000, "wellbeing": -26},"He stayed on the line for two days and was very kind. Then there was nobody on the line.")]},
 {id:"s_alone",category:"family",min:70,max:80,from:2002,to:2026,gate:null,title:"Nobody has been by since Songkran",prompt:"The house is quiet. Your children send money and call on Sundays. The stairs have become a decision, and you have started leaving the radio on so that somebody is talking.",rehearse:"This is real. National Statistical Office data cited by NESDC show the share of older people living alone rose from 6.3 percent in 2002 to 12.9 percent in 2024. (The Nation Thailand, 2026)",options:[opt("ask","Tell your children you are not managing",{"wellbeing": -2, "skills": {"eq": 2}},"It was the hardest phone call of your life. One of them cried. Nobody moved home."),opt("say","Tell them you are fine",{"wellbeing": -10},"You fell in the kitchen in March. It was Sunday before anybody knew."),opt("temple","Spend your days at the temple with the other old people",{"wellbeing": 4},"You peeled garlic and complained with the others. It was enough, most days.")]}
];
const CITY=['khlong-toei','bang-na','sukhumvit','samut-prakan'];
const GATES={country:s=>!CITY.includes(regionAt(s,s.age-1)),city:s=>CITY.includes(regionAt(s,s.age-1)),isan:s=>regionAt(s,s.age-1)==='isan-village',woman:s=>s.intake?.sex==='female',man:s=>s.intake?.sex==='male',parent:s=>{const p={...s.pivotFlags,...s.story?.flags}.parent;return typeof p==='number'&&p<s.age;}};
const cal=s=>{const y=birthYearOf(s);return y===null?null:y+s.age;};
export const SAD_ENCOUNTERS=SAD_SCENES.map(({from,to,gate,...scene})=>({...scene,director:true,eligible:s=>{const c=cal(s);return !!s.intake?.class&&c!==null&&c+4>=from&&c<=to&&(!gate||GATES[gate](s))&&rand(s.seed,s.age,scene.id)<(to-from<4?.5:.09);}}));
